		head.xRot += state.xRot * 0.017453292F * 0.8F;
		ear_r.zRot += Mth.sin(state.ageInTicks * 0.11F + 2.0F) * (0.05F + 0.0F * state.walkAnimationSpeed);
		ear_l.zRot += Mth.sin(state.ageInTicks * 0.11F + 0.0F) * (0.05F + 0.0F * state.walkAnimationSpeed);
		leg_fr.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 3.141592653589793F) * 0.9F * state.walkAnimationSpeed;
		shin_fr.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 4.141592653589793F) * -0.36000000000000004F * state.walkAnimationSpeed;
		leg_fl.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 0.0F) * 0.9F * state.walkAnimationSpeed;
		shin_fl.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 1.0F) * -0.36000000000000004F * state.walkAnimationSpeed;
		leg_br.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 0.0F) * 0.9F * state.walkAnimationSpeed;
		shin_br.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 1.0F) * -0.36000000000000004F * state.walkAnimationSpeed;
		leg_bl.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 3.141592653589793F) * 0.9F * state.walkAnimationSpeed;
		shin_bl.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 4.141592653589793F) * -0.36000000000000004F * state.walkAnimationSpeed;
